import type { Metadata } from "next";

import { DEFAULT_LOCALE, getMessages } from "@/lib/i18n";
import "./globals.css";

const messages = getMessages();

export const metadata: Metadata = {
  title: messages.metadata.title,
  description: messages.metadata.description,
  // Icons come from the file conventions next to this layout (favicon.ico,
  // icon1/icon2.png, apple-icon.png), generated by scripts/brand-assets.mjs.
  applicationName: messages.metadata.title,
  appleWebApp: { title: messages.metadata.title },
};

export default function RootLayout({ children }: LayoutProps<"/">) {
  return (
    <html lang={DEFAULT_LOCALE} className="h-full antialiased">
      <body className="flex min-h-full flex-col">{children}</body>
    </html>
  );
}
